    n = len(words)
    for i in range(n):
        for j in range(i + 1, n):
            shares_letter = False
            for ch1 in words[i]:                                   # compares every character against every other
                for ch2 in words[j]:
                    if ch1 == ch2:
                        shares_letter = True
                        break
                if shares_letter:
                    break
            if not shares_letter:
                best = max(best, len(words[i]) * len(words[j]))
