import java.util.*;

public class Main {
    int maxProduct(String[] words) {
        int best = 0;
        int n = words.length;
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                boolean sharesLetter = false;
                for (char ch1 : words[i].toCharArray()) {                 // compares every character against every other
                    for (char ch2 : words[j].toCharArray()) {
                        if (ch1 == ch2) { sharesLetter = true; break; }
                    }
                    if (sharesLetter) break;
                }
                if (!sharesLetter) {
                    best = Math.max(best, words[i].length() * words[j].length());
                }
            }
        }
        return best;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.maxProduct(new String[]{"abcw", "baz", "foo", "bar", "xtfn", "abcdef"}));
    }
}

