def max_product(words):
    masks = []
    for word in words:
        mask = 0
        for ch in word:
            mask |= (1 << (ord(ch) - ord('a')))                    # set the bit for this letter
        masks.append(mask)

    best = 0
    n = len(words)
    for i in range(n):
        for j in range(i + 1, n):
            if masks[i] & masks[j] == 0:                              # O(1) check for any shared letter
                best = max(best, len(words[i]) * len(words[j]))
    return best


if __name__ == "__main__":
    print(max_product(["abcw", "baz", "foo", "bar", "xtfn", "abcdef"]))

